{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // ─── Model ───

/** @planks("a todo item {string} exists") @planks("a completed todo item {string} exists") @planks("an active todo item {string} exists") @planks("todo items {string} and {string} exist") @planks("todo items {string} and {string} and {string} exist") @planks("active todo items {string} and {string} exist") @planks("completed todo items {string} and {string} exist") @planks("{string} is completed") */
  function TodoModel(storageKey) {
    this.storageKey = storageKey || STORAGE_KEY;
    this.todos = this.load();
  }

  TodoModel.prototype.load = function () {
    var data;
    try {
      data = JSON.parse(localStorage.getItem(this.storageKey) || '[]');
    } catch (e) {
      data = [];
    }
    return data;
  };

  TodoModel.prototype.save = function () {
    localStorage.setItem(this.storageKey, JSON.stringify(this.todos));
  };

  TodoModel.prototype.add = function (title) {
    var todo = {
      id: Date.now() + Math.random(),
      title: title,
      completed: false
    };
    this.todos.push(todo);
    this.save();
    return todo;
  };

  TodoModel.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  TodoModel.prototype.toggle = function (id) {
    var todo = this.todos.filter(function (t) { return t.id === id; })[0];
    if (todo) {
      todo.completed = !todo.completed;
      this.save();
    }
  };

  TodoModel.prototype.toggleAll = function (completed) {
    this.todos.forEach(function (t) { t.completed = completed; });
    this.save();
  };

  TodoModel.prototype.update = function (id, title) {
    var todo = this.todos.filter(function (t) { return t.id === id; })[0];
    if (todo) {
      todo.title = title;
      this.save();
    }
  };

  TodoModel.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
  };

  TodoModel.prototype.getActive = function () {
    return this.todos.filter(function (t) { return !t.completed; });
  };

  TodoModel.prototype.getCompleted = function () {
    return this.todos.filter(function (t) { return t.completed; });
  };

  // ─── View ───

/** @planks("I type {string} into the new-todo input and press Enter") @planks("I create a new todo {string}") @planks("the new-todo input is cleared") @planks("no new todo item is created") @planks("I click the toggle checkbox on {string}") @planks("I mark {string} as completed") @planks("I unmark {string}") @planks("I click the {string} checkbox") @planks("I click the {string} button") @planks("I click the destroy button on {string}") @planks("I double-click the label of {string}") @planks("I change the edit input to {string} and press Enter") @planks("I change the edit input to {string} and press Tab to blur") @planks("I change the edit input to {string} and press Escape") @planks("I clear the edit input and press Enter") @planks("the page is reloaded") @planks("I navigate to route {string}") @planks("the app is at route {string}") */
  function TodoView(model) {
    this.model = model;
    this.$newTodo = document.querySelector('.new-todo');
    this.$toggleAll = document.querySelector('.toggle-all');
    this.$todoList = document.querySelector('.todo-list');
    this.$footer = document.querySelector('.footer');
    this.$main = document.querySelector('.main');
    this.$todoCount = document.querySelector('.todo-count');
    this.$clearCompleted = document.querySelector('.clear-completed');
    this.$filters = document.querySelectorAll('.filters a');

    this.currentFilter = 'all';
    this.editingId = null;

    this.bindEvents();
    this.render();
  }

  TodoView.prototype.bindEvents = function () {
    var self = this;

    // New todo
    this.$newTodo.addEventListener('keypress', function (e) {
      if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
        var title = self.$newTodo.value.trim();
        if (title) {
          self.model.add(title);
          self.$newTodo.value = '';
          self.render();
        }
      }
    });

    // Toggle all
    this.$toggleAll.addEventListener('change', function () {
      var completed = self.$toggleAll.checked;
      self.model.toggleAll(completed);
      self.render();
    });

    // Todo list events (delegation)
    this.$todoList.addEventListener('click', function (e) {
      var li = self._getLi(e.target);
      if (!li) return;

      // Toggle checkbox
      if (e.target.classList.contains('toggle')) {
        var id = Number(li.dataset.id);
        self.model.toggle(id);
        self.render();
      }

      // Destroy button
      if (e.target.classList.contains('destroy')) {
        var id = Number(li.dataset.id);
        self.model.remove(id);
        self.render();
      }
    });

    // Double-click to edit
    this.$todoList.addEventListener('dblclick', function (e) {
      var label = e.target;
      if (label.tagName !== 'LABEL') return;
      var li = self._getLi(label);
      if (!li) return;

      self._enterEditMode(li);
    });

    // Edit events (delegation)
    this.$todoList.addEventListener('keydown', function (e) {
      if (self.editingId === null) return;
      var input = e.target;
      if (!input.classList.contains('edit')) return;

      if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
        e.preventDefault();
        self._finishEdit(input);
      } else if (e.keyCode === ESCAPE_KEY || e.key === 'Escape') {
        self._cancelEdit(input);
      }
    });

    // Blur saves edit
    this.$todoList.addEventListener('focusout', function (e) {
      if (self.editingId === null) return;
      var input = e.target;
      if (!input.classList.contains('edit')) return;
      self._finishEdit(input);
    });

    // Clear completed
    this.$clearCompleted.addEventListener('click', function () {
      self.model.clearCompleted();
      self.render();
    });

    // Hash change (routing)
    window.addEventListener('hashchange', function () {
      self._setFilterFromHash();
      self.render();
    });
  };

  TodoView.prototype._getLi = function (el) {
    while (el && el.tagName !== 'LI') {
      el = el.parentNode;
    }
    return el;
  };

  TodoView.prototype._enterEditMode = function (li) {
    var id = Number(li.dataset.id);
    this.editingId = id;
    this.render();

    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
      editInput.setSelectionRange(editInput.value.length, editInput.value.length);
    }
  };

  TodoView.prototype._finishEdit = function (input, fromKeydown) {
    var li = this._getLi(input);
    if (!li) {
      // called from blur, li might still be live
      li = input.closest ? input.closest('li') : null;
      if (!li) return;
    }

    var id = Number(li.dataset.id);
    var title = input.value.trim();

    if (title) {
      this.model.update(id, title);
    } else {
      this.model.remove(id);
    }

    this.editingId = null;
    this.render();
  };

  TodoView.prototype._cancelEdit = function (input) {
    var li = this._getLi(input);
    if (!li) return;
    var id = Number(li.dataset.id);
    var todo = this.model.todos.filter(function (t) { return t.id === id; })[0];
    if (todo) {
      input.value = todo.title;
    }
    this.editingId = null;
    this.render();
  };

  TodoView.prototype._setFilterFromHash = function () {
    var hash = window.location.hash.replace('#/', '') || 'all';
    if (hash === '') hash = 'all';
    this.currentFilter = hash;
  };

  TodoView.prototype.render = function () {
    // Set filter from hash on initial render
    if (!this._filterSet) {
      this._setFilterFromHash();
      this._filterSet = true;
    }

    var todos = this.model.todos;
    var activeCount = this.model.getActive().length;
    var completedCount = this.model.getCompleted().length;
    var hasTodos = todos.length > 0;

    // Toggle main and footer visibility
    this.$main.style.display = hasTodos ? 'block' : 'none';
    this.$footer.style.display = hasTodos ? 'block' : 'none';

    // Toggle-all state
    this.$toggleAll.checked = hasTodos && activeCount === 0;

    // Clear completed visibility
    this.$clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Filtered list
    var filtered;
    if (this.currentFilter === 'active') {
      filtered = this.model.getActive();
    } else if (this.currentFilter === 'completed') {
      filtered = this.model.getCompleted();
    } else {
      filtered = todos;
    }

    // Build list HTML
    var html = '';
    filtered.forEach(function (todo) {
      var liClass = '';
      if (todo.completed) liClass += 'completed ';
      if (this.editingId === todo.id) liClass += 'editing';

      html += '<li data-id="' + todo.id + '"';
      if (liClass) html += ' class="' + liClass.trim() + '"';
      html += '>';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"';
      if (todo.completed) html += ' checked';
      html += '>';
      html += '<label>' + this._escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';

      if (this.editingId === todo.id) {
        html += '<input class="edit" value="' + this._escapeHtml(todo.title) + '">';
      } else {
        html += '<input class="edit" value="' + this._escapeHtml(todo.title) + '" style="display:none">';
      }
      html += '</li>';
    }, this);

    this.$todoList.innerHTML = html;

    // Focus edit input if editing
    if (this.editingId !== null) {
      var editInput = this.$todoList.querySelector('.editing .edit');
      if (editInput && document.activeElement !== editInput) {
        editInput.focus();
        editInput.setSelectionRange(editInput.value.length, editInput.value.length);
      }
    }

    // Todo count
    var countText = activeCount + ' item';
    if (activeCount !== 1) countText += 's';
    countText += ' left';
    this.$todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + countText.slice(countText.indexOf(' ') + 1);

    // Filter link selection
    this.$filters.forEach(function (a) {
      var href = a.getAttribute('href').replace('#/', '') || 'all';
      if (href === '') href = 'all';
      if (href === this.currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }, this);
  };

  TodoView.prototype._escapeHtml = function (str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  };

  // ─── Bootstrap ───

  var model = new TodoModel();
  var view = new TodoView(model);
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

function esc(s) {
  return s.replace(/'/g, "\\'").replace(/\\/g, '\\\\');
}

function findLi(t) {
  return "Array.from(document.querySelectorAll('.todo-list li')).filter(function(l){var lb=l.querySelector('div.view label');return lb&&lb.textContent==='" + esc(t) + "';})[0]";
}

function liExists(t) { return findLi(t) + '!==undefined'; }
function findToggle(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view input.toggle'):null;})()"; }
function findDes(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view button.destroy'):null;})()"; }
function findLabel(t) { return "(function(){var li="+findLi(t)+";return li?li.querySelector('div.view label'):null;})()"; }
function liClass(t,c){ return "(function(){var li="+findLi(t)+";return li?li.classList.contains('"+esc(c)+"'):false;})()"; }
function toggleChk(t){ return "(function(){var t="+findToggle(t)+";return t?t.checked:false;})()"; }
function mapSel(id){if(id==='#main')return '.main';if(id==='#footer')return '.footer';return id;}

Given('the todo app is loaded with a fresh localStorage', function() { this.loadApp(); this.clearLocalStorage(); });
Given('the app has no todos', function() { this.loadApp(); this.clearLocalStorage(); this.evaluate("document.querySelector('.todo-list').innerHTML='';"); });
Given('a todo item {string} exists', function(t) { this.clickElement('.new-todo'); this.setInputValue('.new-todo',t); this.pressEnter('.new-todo'); });
Given('a completed todo item {string} exists', function(t) { this.clickElement('.new-todo'); this.setInputValue('.new-todo',t); this.pressEnter('.new-todo'); this.clickElement('li:last-child div.view input.toggle'); });
Given('an active todo item {string} exists', function(t) { this.clickElement('.new-todo'); this.setInputValue('.new-todo',t); this.pressEnter('.new-todo'); });
Given('todo items {string} and {string} exist', function(a,b) { var self=this; [a,b].forEach(function(t){self.setInputValue('.new-todo',t);self.pressEnter('.new-todo');}); });
Given('todo items {string} and {string} and {string} exist', function(a,b,c) { var self=this; [a,b,c].forEach(function(t){self.setInputValue('.new-todo',t);self.pressEnter('.new-todo');}); });
Given('active todo items {string} and {string} exist', function(a,b) { var self=this; [a,b].forEach(function(t){self.setInputValue('.new-todo',t);self.pressEnter('.new-todo');}); });
Given('completed todo items {string} and {string} exist', function(a,b) {
  var self=this; [a,b].forEach(function(t){self.setInputValue('.new-todo',t);self.pressEnter('.new-todo');});
  var c=this.querySelectorAllCount('.todo-list li');
  for(var i=0;i<c;i++) this.clickElement('.todo-list li:nth-child('+(i+1)+') div.view input.toggle');
});
Given('all todo items are completed', function() { this.clickElement('.toggle-all'); });
Given('{string} is completed', function(t){var sel=findToggle(t);this.page.evaluate("(function(){var tt="+sel+";if(tt)tt.click();})()");});

Given('the app is at route {string}', function(r) { this.page.evaluate("window.location.hash='"+esc(r)+"';window.dispatchEvent(new HashChangeEvent('hashchange'));"); });
Given('the todo {string} is being edited', function(t) {
  var exists=this.evaluate(liExists(t));
  if(!exists){this.setInputValue('.new-todo',t);this.pressEnter('.new-todo');}
  this.page.evaluate("(function(){var li="+findLi(t)+";if(li){var lb=li.querySelector('div.view label');if(lb)lb.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));}})()");
});
Given('the input field is focused', function() { this.page.evaluate('document.querySelector(".new-todo").focus()'); });

Given('{string} is visible under the completed filter', function(t) { this.page.evaluate("window.location.hash='#/completed';window.dispatchEvent(new HashChangeEvent('hashchange'));"); });

When('I type {string} into the new-todo input and press Enter', function(t){this.setInputValue('.new-todo',t);this.pressEnter('.new-todo');});
When('I click the toggle checkbox on {string}', function(t){this.page.evaluate("(function(){var t="+findToggle(t)+";if(t)t.click();})()");});
When('I click the {string} checkbox', function(id){this.clickElement('#'+esc(id));});
When('I click the {string} button', function(t){if(t==='Clear completed')this.clickElement('.clear-completed');});
When('I click the destroy button on {string}', function(t){this.page.evaluate("(function(){var d="+findDes(t)+";if(d)d.click();})()");});
When('I double-click the label of {string}', function(t){this.page.evaluate("(function(){var li="+findLi(t)+";if(li){var lb=li.querySelector('div.view label');if(lb)lb.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));}})()");});

When('I change the edit input to {string} and press Enter', function(t) {
  this.page.evaluate("(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='"+esc(t)+"';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',keyCode:13,bubbles:true}));}})()");
});

When('I change the edit input to {string} and press Tab to blur', function(t) {
  this.page.evaluate("(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='"+esc(t)+"';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',keyCode:9,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Tab',keyCode:9,bubbles:true}));el.dispatchEvent(new FocusEvent('focusout',{bubbles:true}));}})()");
});

When('I change the edit input to {string} and press Escape', function(t) {
  this.page.evaluate("(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='"+esc(t)+"';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',keyCode:27,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Escape',keyCode:27,bubbles:true}));}})()");
});

When('I clear the edit input and press Enter', function() {
  this.page.evaluate("(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}if(el){el.value='';el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));el.dispatchEvent(new KeyboardEvent('keyup',{key:'Enter',keyCode:13,bubbles:true}));}})()");
});

When('I mark {string} as completed', function(t){this.page.evaluate("(function(){var t="+findToggle(t)+";if(t)t.click();})()");});
When('I unmark {string}', function(t){this.page.evaluate("window.location.hash='#/completed';window.dispatchEvent(new HashChangeEvent('hashchange'));");this.page.evaluate("(function(){var t="+findToggle(t)+";if(t)t.click();})()");this.page.evaluate("window.location.hash='#/active';window.dispatchEvent(new HashChangeEvent('hashchange'));");});
When('the page is reloaded', function(){this.loadApp();this.page.evaluate('if(window.onhashchange)window.onhashchange();');});
When('I navigate to route {string}', function(r){this.page.evaluate("window.location.hash='"+esc(r)+"';window.dispatchEvent(new HashChangeEvent('hashchange'));");});
When('I create a new todo {string}', function(t){this.setInputValue('.new-todo',t);this.pressEnter('.new-todo');});

Then('the {string} section is not visible', function(id){assert.strictEqual(this.isVisible(mapSel(id)),false,'Expected '+id+' hidden');});
Then('the {string} section is visible', function(id){assert.strictEqual(this.isVisible(mapSel(id)),true,'Expected '+id+' visible');});
Then('a new todo item with title {string} appears in the list', function(t){assert.strictEqual(this.evaluate(liExists(t)),true,'Expected "'+t+'" to appear');});
Then('the new todo {string} appears in the list', function(t){assert.strictEqual(this.evaluate(liExists(t)),true,'Expected "'+t+'" to appear');});

Then('the new-todo input is cleared', function(){assert.strictEqual(this.page.evaluate('document.querySelector(".new-todo").value'),'','Expected cleared');});
Then('no new todo item is created', function(){assert.strictEqual(this.querySelectorAllCount('.todo-list li'),0,'Expected no todos');});
Then('the {string} item has the {string} class', function(t,c){assert.strictEqual(this.evaluate(liClass(t,c)),true,'Expected "'+t+'" has "'+c+'"');});
Then('the {string} item does not have the {string} class', function(t,c){assert.strictEqual(this.evaluate(liClass(t,c)),false,'Expected "'+t+'" NOT "'+c+'"');});
Then('the toggle checkbox on {string} is checked', function(t){assert.strictEqual(this.evaluate(toggleChk(t)),true,'Expected toggle on "'+t+'" checked');});
Then('the toggle checkbox on {string} is not checked', function(t){assert.strictEqual(this.evaluate(toggleChk(t)),false,'Expected toggle on "'+t+'" not checked');});
Then('the {string} checkbox is checked', function(id){assert.strictEqual(this.page.evaluate("document.querySelector('#"+esc(id)+"')?document.querySelector('#"+esc(id)+"').checked:false"),true,'Expected "'+id+'" checked');});
Then('the {string} checkbox is not checked', function(id){assert.strictEqual(this.page.evaluate("document.querySelector('#"+esc(id)+"')?document.querySelector('#"+esc(id)+"').checked:false"),false,'Expected "'+id+'" not checked');});
Then('all todo items have the {string} class', function(c){assert.strictEqual(this.page.evaluate("document.querySelectorAll('.todo-list li').length>0&&Array.from(document.querySelectorAll('.todo-list li')).every(function(l){return l.classList.contains('"+esc(c)+"');})"),true,'Expected all have "'+c+'"');});

Then('the todo {string} has the {string} class', function(t,c){assert.strictEqual(this.evaluate(liClass(t,c)),true,'Expected "'+t+'" has "'+c+'"');});
Then('no list item has the {string} class', function(c){assert.strictEqual(this.page.evaluate("Array.from(document.querySelectorAll('.todo-list li')).some(function(l){return l.classList.contains('"+esc(c)+"');})"),false,'Expected no item has "'+c+'"');});

Then('no todo item has the {string} class', function(c){assert.strictEqual(this.page.evaluate("Array.from(document.querySelectorAll('.todo-list li')).some(function(l){return l.classList.contains('"+esc(c)+"');})"),false,'Expected no item has "'+c+'"');});
Then('the todo {string} does not exist in the list', function(t){assert.strictEqual(this.evaluate(liExists(t)),false,'Expected "'+t+'" NOT exist');});
Then('the todo {string} still exists in the list', function(t){assert.strictEqual(this.evaluate(liExists(t)),true,'Expected "'+t+'" to exist');});
Then('the {string} button is not visible', function(t){var v;if(t==='Clear completed')v=this.isVisible('.clear-completed');assert.strictEqual(v,false,'Expected "'+t+'" btn hidden');});
Then('the {string} button is visible', function(t){var v;if(t==='Clear completed')v=this.isVisible('.clear-completed');assert.strictEqual(v,true,'Expected "'+t+'" btn visible');});
Then('the {string} list item has the {string} class', function(t,c){assert.strictEqual(this.evaluate(liClass(t,c)),true,'Expected "'+t+'" has "'+c+'"');});
Then('the {string} list item does not have the {string} class', function(t,c){assert.strictEqual(this.evaluate(liClass(t,c)),false,'Expected "'+t+'" NOT "'+c+'"');});

Then('the edit input contains {string}', function(t) {
  var v=this.page.evaluate("(function(){var el=document.querySelector('input.edit');if(!el||el.style.display==='none'){var els=document.querySelectorAll('input.edit');for(var i=0;i<els.length;i++){if(els[i].offsetParent!==null){el=els[i];break}}}return el?el.value:null;})()");
  assert.strictEqual(v,t,'Expected edit "'+t+'"');
});

Then('the todo label shows {string}', function(t){assert.strictEqual(this.evaluate("(function(){var lb="+findLabel(t)+";return lb?lb.textContent:null;})()"),t,'Expected label "'+t+'"');});
Then('the todo label still shows {string}', function(t){assert.strictEqual(this.evaluate("(function(){var lb="+findLabel(t)+";return lb?lb.textContent:null;})()"),t,'Expected label "'+t+'"');});

Then('the todo-count element shows {string}', function(e){
  var t=this.page.evaluate("(function(){var el=document.querySelector('.todo-count');return el?el.textContent.trim():null;})()");
  assert.strictEqual(t,e,'Expected count "'+e+'"');
});

